<section id="staff" data-access-panel><h2 tabindex="-1">User Accounts</h2>
<?php if($accessCanCreateUser):?><details class="card"><summary>Create User Account</summary><form method="post"><label for="new-name">Full name</label><input id="new-name" name="name" maxlength="120" required><label for="new-email">Email</label><input id="new-email" name="email" type="email" maxlength="190" required><label for="temporary-password">Temporary password</label><div class="password"><input id="temporary-password" name="password" type="password" minlength="12" maxlength="72" autocomplete="new-password" required><button type="button" class="secondary" data-password-toggle="temporary-password" aria-pressed="false" aria-label="Show password">Show</button></div><small>The new account starts with the clerk role and must change its password at first sign-in. Share the temporary password privately.</small><?php access_management_fields('save_user')?><p class="access-actions"><button>Create Account</button><button type="button" class="secondary" data-access-cancel hidden>Cancel</button></p></form></details><?php endif?>
<?php foreach($users as $staff):?><details class="card access-record" data-access-account="<?=(int)$staff['id']?>" <?=$accessSelectedAccount===(int)$staff['id']?'open':''?>><summary><?=access_h($staff['name'])?> · <?=access_h($staff['email'])?> · <?=$staff['active']?'Active':'Inactive'?></summary><p>User #<?=(int)$staff['id']?> · Roles: <?=access_h(implode(', ',array_map(static fn($roleId)=>$accessRoleNames[$roleId] ?? 'Unknown',$userRoles[$staff['id']] ?? [])))?:'None Assigned'?><?=$staff['must_change_password']?' · Password change required':''?></p><div>
<?php if($accessSelectedAccount===(int)$staff['id']):?>
<?php if($can('users.manage')&&$accessUserEditable[$staff['id']]):?><details class="access-action" name="account-<?=(int)$staff['id']?>"><summary>Edit Account</summary><form method="post"><label for="name-<?=(int)$staff['id']?>">Name</label><input id="name-<?=(int)$staff['id']?>" name="name" value="<?=access_h($staff['name'])?>" maxlength="120" required><label for="email-<?=(int)$staff['id']?>">Email</label><input id="email-<?=(int)$staff['id']?>" name="email" type="email" value="<?=access_h($staff['email'])?>" maxlength="190" required><?php access_management_fields('save_user',(int)$staff['id'])?><p class="access-actions"><button>Save Account</button><button type="button" class="secondary" data-access-cancel hidden>Cancel</button></p></form></details>
<?php if((int)$staff['id']!==(int)$user['id']):?><details class="access-action" name="account-<?=(int)$staff['id']?>"><summary><?=$staff['active']?'Deactivate Account':'Reactivate Account'?></summary><form method="post"><input type="hidden" name="active" value="<?=$staff['active']?'0':'1'?>"><p>Deactivation retains historical attribution and prevents sign-in. The last active administrator is protected.</p><?php access_management_fields('set_active',(int)$staff['id'])?><p class="access-actions"><button><?=$staff['active']?'Deactivate':'Reactivate'?></button><button type="button" class="secondary" data-access-cancel hidden>Cancel</button></p></form></details><?php endif?>
<details class="access-action" name="account-<?=(int)$staff['id']?>"><summary>Revoke Sessions</summary><form method="post"><p>Sign this account out on its next request.</p><?php access_management_fields('revoke_sessions',(int)$staff['id'])?><p class="access-actions"><button>Revoke Sessions</button><button type="button" class="secondary" data-access-cancel hidden>Cancel</button></p></form></details><?php endif?>
<?php if($can('roles.assign')&&$accessUserEditable[$staff['id']]):?><details class="access-action" name="account-<?=(int)$staff['id']?>"><summary>Assigned Roles</summary><form method="post" class="checks" data-permission-preview><?php foreach($roles as $role):?><label><input type="checkbox" name="ids[]" value="<?=(int)$role['id']?>" data-permission-labels="<?=access_h(json_encode((object)array_intersect_key($accessPreviewLabels,array_flip($rolePrivileges[$role['id']]??[])),JSON_THROW_ON_ERROR))?>" <?=in_array((int)$role['id'],$userRoles[$staff['id']] ?? [],true)?'checked':''?>><?=access_h($role['name'])?></label><?php endforeach?><p data-permission-changes role="status" hidden></p><?php access_management_fields('assign_roles',(int)$staff['id'])?><p class="access-actions"><button>Save Roles</button><button type="button" class="secondary" data-access-cancel hidden>Cancel</button></p></form></details><?php endif?>
<?php elseif($accessUserEditable[$staff['id']]&&($can('users.manage')||$can('roles.assign'))):?><p><a href="<?=access_h(access_url('users.php?account='.(int)$staff['id']))?>#staff">Manage Account</a></p><?php endif?>
<?php if(!$accessUserEditable[$staff['id']]):?><p class="muted">Read Only: This Account Is Above Your Authority.</p><?php endif?></div></details><?php endforeach?></section>
